import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// Arthur David ("Lutando por um Amapá cada vez melhor"). Motion de finalização: vinheta de logo para colar no fim dos
// vídeos de tráfego pago. Cópia do jeito da referência do cliente (TikTok @suamarca, "vinheta candidato animada"):
// linha que abre em duas colunas, letra A gigante em camadas, anéis girando, círculo que fecha a tela, A que salta com
// sombra deslocada, giro em 3D e o nome montado letra por letra. Trocados o logo e as cores (pedido do cliente):
// azul-marinho, azul-bebê e amarelo. O logo é o PNG do Drive dele separado em camadas (public/arthur/).
// Sem locução (vinheta). A versão com voz usa a mesma animação, mais longa no fim (prop fim).

export const AR_FPS = 30;
export const AR_FRAMES = 210;
// versão com a assinatura falada (voz-v1, o locutor): a voz começa em 4,13 s, junto com as letras, e termina em 7,52 s
export const AR_VOZ_FRAMES = 249;

const NAVY = "#0B1F4D";
const BEBE = "#A9D3F5";
const AMARELO = "#FFC629";
const PAPEL = "#F5F7FB";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.bezier(0.34, 1.56, 0.64, 1);
const IN = Easing.bezier(0.55, 0, 0.9, 0.4);

// logo em camadas: 1801 x 524 px; cortes das letras do nome em x (DAV vem junto e é dividido em três)
const LW = 1801;
const LH = 524;
const CORTES: [number, number][] = [[486, 616], [618, 742], [748, 877], [885, 1010], [1018, 1144], [1210, 1338], [1338, 1466], [1466, 1600], [1604, 1664], [1672, 1801]];
// símbolo (A + faixa) dentro do logo
const SX0 = 0;
const SX1 = 605;

// silhueta do A em uma cor só (máscara do PNG do símbolo)
const Silhueta: React.FC<{ cor: string; w: number; style?: React.CSSProperties }> = ({ cor, w, style }) => {
  const h = (w * LH) / (SX1 - SX0);
  return (
    <div
      style={{
        position: "absolute", width: w, height: h, left: -w / 2, top: -h / 2, background: cor,
        WebkitMaskImage: `url(${staticFile("arthur/simbolo.png")})`, WebkitMaskSize: `${(w * LW) / (SX1 - SX0)}px ${h}px`,
        WebkitMaskPosition: "0 0", WebkitMaskRepeat: "no-repeat", ...style,
      }}
    />
  );
};

const Simbolo: React.FC<{ w: number }> = ({ w }) => {
  const h = (w * LH) / (SX1 - SX0);
  return (
    <div style={{ position: "absolute", width: w, height: h, left: -w / 2, top: -h / 2, overflow: "hidden" }}>
      <Img src={staticFile("arthur/simbolo.png")} style={{ position: "absolute", left: 0, top: 0, width: (w * LW) / (SX1 - SX0), height: h }} />
    </div>
  );
};

const Centro: React.FC<{ style?: React.CSSProperties; children: React.ReactNode }> = ({ style, children }) => (
  <div style={{ position: "absolute", left: 540, top: 960, width: 0, height: 0, ...style }}>{children}</div>
);

// 1. linha que abre em duas colunas (0 a 1,0 s)
const Abertura: React.FC<{ f: number }> = ({ f }) => {
  const linha = interpolate(f, [4, 12], [0, 1], { ...cl, easing: OUT });
  const hEsq = interpolate(f, [11, 24], [10, 1920], { ...cl, easing: INOUT });
  const hDir = interpolate(f, [14, 27], [10, 1920], { ...cl, easing: INOUT });
  const faixa = interpolate(f, [16, 26], [0, 46], { ...cl, easing: OUT });
  const cam = interpolate(f, [0, 30], [1.18, 1.0], { ...cl, easing: OUT });
  const rot = interpolate(f, [0, 30], [-4, 0], { ...cl, easing: OUT });
  return (
    <AbsoluteFill style={{ background: PAPEL, transform: `scale(${cam}) rotate(${rot}deg)` }}>
      <div style={{ position: "absolute", right: 540, width: 540 * linha, top: 960 - hEsq / 2, height: hEsq, background: NAVY }} />
      <div style={{ position: "absolute", left: 540, width: 540 * linha, top: 960 - hDir / 2, height: hDir, background: BEBE }} />
      <div style={{ position: "absolute", left: 540 - faixa / 2, width: faixa, top: 0, height: 1920, background: AMARELO }} />
    </AbsoluteFill>
  );
};

// 2. A gigante em camadas sobre as colunas (0,9 a 1,5 s)
const Camadas: React.FC<{ f: number }> = ({ f }) => {
  const t = f - 27;
  const s1 = interpolate(t, [0, 16], [5.2, 2.6], { ...cl, easing: OUT });
  const s2 = interpolate(t, [2, 16], [4.2, 1.9], { ...cl, easing: OUT });
  const s3 = interpolate(t, [4, 16], [3.2, 1.25], { ...cl, easing: OUT });
  const r = interpolate(t, [0, 16], [8, -3], cl);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 0, width: 540, height: 1920, background: NAVY }} />
      <div style={{ position: "absolute", left: 540, width: 540, height: 1920, background: BEBE }} />
      <Centro style={{ transform: `rotate(${r}deg)` }}>
        <Silhueta cor={BEBE} w={600} style={{ transform: `scale(${s1})` }} />
        <Silhueta cor={PAPEL} w={600} style={{ transform: `scale(${s2})` }} />
        <Silhueta cor={NAVY} w={600} style={{ transform: `scale(${s3}) translate(10px, 0)` }} />
      </Centro>
    </AbsoluteFill>
  );
};

// 3. anéis girando e círculo que fecha a tela em azul-marinho (1,4 a 2,1 s)
const Aneis: React.FC<{ f: number }> = ({ f }) => {
  const t = f - 42;
  const esc = interpolate(t, [0, 18], [0.35, 1.5], { ...cl, easing: OUT });
  const fecha = interpolate(t, [10, 21], [0, 1150], { ...cl, easing: Easing.bezier(0.7, 0, 0.84, 0) });
  const anel = (r: number, w: number, cor: string, arco: number, giro: number, i: number) => {
    const c = 2 * Math.PI * r;
    return (
      <circle key={i} cx={0} cy={0} r={r} fill="none" stroke={cor} strokeWidth={w} strokeDasharray={`${c * arco} ${c}`}
        transform={`rotate(${giro + t * (i % 2 ? -14 : 11)})`} />
    );
  };
  return (
    <AbsoluteFill style={{ background: PAPEL }}>
      <svg width={1080} height={1920} viewBox="-540 -960 1080 1920" style={{ position: "absolute" }}>
        <g transform={`scale(${esc})`}>
          {anel(110, 70, NAVY, 0.78, 20, 0)}
          {anel(200, 54, BEBE, 0.66, 160, 1)}
          {anel(290, 64, NAVY, 0.72, 250, 2)}
          {anel(372, 26, AMARELO, 0.45, 60, 3)}
          {anel(450, 70, BEBE, 0.6, 300, 4)}
        </g>
        <circle cx={0} cy={0} r={fecha} fill={NAVY} />
      </svg>
    </AbsoluteFill>
  );
};

// 4. o A salta com sombra deslocada, segura e gira em 3D (2,1 a 4,1 s)
const Salto: React.FC<{ f: number }> = ({ f }) => {
  const t = f - 63;
  const pop = interpolate(t, [0, 10], [0, 1], { ...cl, easing: BACK });
  const sombra = interpolate(t, [4, 12], [0, 1], { ...cl, easing: OUT });
  const push = interpolate(t, [10, 48], [1, 1.1], cl);
  const giro = interpolate(t, [44, 58], [0, -48], { ...cl, easing: IN });
  const incl = interpolate(t, [44, 58], [0, -9], { ...cl, easing: IN });
  const sai = interpolate(t, [52, 59], [0, -1500], { ...cl, easing: IN });
  const esc = interpolate(t, [44, 58], [1, 1.35], { ...cl, easing: IN });
  return (
    <AbsoluteFill style={{ background: NAVY, perspective: 1600 }}>
      <Centro style={{ transform: `translateX(${sai}px) rotateY(${giro}deg) rotateZ(${incl}deg) scale(${pop * push * esc})` }}>
        <Silhueta cor={BEBE} w={640} style={{ transform: `translate(${30 * sombra}px, ${26 * sombra}px)` }} />
        <Simbolo w={640} />
      </Centro>
    </AbsoluteFill>
  );
};

// 5. logo montado: A entra pela esquerda, letras saltam uma a uma, slogan abre em faixa (4,1 s em diante)
const Logo: React.FC<{ f: number }> = ({ f }) => {
  const t = f - 120;
  const W = 900;
  const k = W / LW;
  const H = LH * k;
  const sX = interpolate(t, [0, 11], [-520, 0], { ...cl, easing: BACK });
  const sO = interpolate(t, [0, 4], [0, 1], cl);
  const tag = interpolate(t, [30, 42], [0, 100], { ...cl, easing: OUT });
  const cam = interpolate(t, [0, 130], [0.96, 1.05], cl);
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      <div style={{ position: "absolute", left: 540 - W / 2, top: 960 - H / 2, width: W, height: H, transform: `scale(${cam})` }}>
        <Img src={staticFile("arthur/slogan.png")} style={{ position: "absolute", width: W, height: H, clipPath: `inset(0 ${100 - tag}% 0 0)` }} />
        {CORTES.map(([x0, x1], i) => {
          const a = 6 + i * 2;
          const p = interpolate(t, [a, a + 9], [0, 1], { ...cl, easing: BACK });
          const o = interpolate(t, [a, a + 3], [0, 1], cl);
          const cx = ((x0 + x1) / 2) * k;
          return (
            <div key={i} style={{
              position: "absolute", inset: 0, opacity: o, clipPath: `inset(-40% ${100 - (x1 / LW) * 100}% -40% ${(x0 / LW) * 100}%)`,
              transform: `translateY(${(1 - p) * 90}px) scale(${0.5 + 0.5 * p})`, transformOrigin: `${cx}px ${H * 0.4}px`,
            }}>
              <Img src={staticFile("arthur/nome.png")} style={{ position: "absolute", width: W, height: H }} />
            </div>
          );
        })}
        <Img src={staticFile("arthur/simbolo.png")} style={{ position: "absolute", width: W, height: H, opacity: sO, transform: `translateX(${sX}px)` }} />
      </div>
    </AbsoluteFill>
  );
};

export const Vinheta: React.FC<{ fim?: number }> = () => {
  const f = useCurrentFrame();
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {f < 28 && <Abertura f={f} />}
      {f >= 27 && f < 43 && <Camadas f={f} />}
      {f >= 42 && f < 64 && <Aneis f={f} />}
      {f >= 63 && f < 121 && <Salto f={f} />}
      {f >= 120 && <Logo f={f} />}
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { AR_FPS, AR_VOZ_FRAMES, Vinheta } from "./Vinheta";

const Root: React.FC = () => (
  <>
    <Composition id="Vinheta" component={Vinheta} durationInFrames={AR_VOZ_FRAMES} fps={AR_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
